#!/bin/bash -xe
exec > >(tee /var/log/user-data.log|logger -t user-data -s 2>/dev/console) 2>&1
echo "Starting SGX node setup"

# Update system
apt-get update -y
apt-get install -y build-essential git cmake libssl-dev curl jq

# Set up Intel SGX
mkdir -p /opt/intel
cd /opt/intel
curl -O https://download.01.org/intel-sgx/sgx-linux/2.14/distro/ubuntu20.04-server/sgx_linux_x64_sdk_2.14.100.2.bin
chmod +x sgx_linux_x64_sdk_2.14.100.2.bin
echo -e 'no\n/opt/intel' | ./sgx_linux_x64_sdk_2.14.100.2.bin
source /opt/intel/sgxsdk/environment

# Configure TEE environment
mkdir -p /opt/rhombus/tee
cd /opt/rhombus/tee

# Configure TEE node
export TEE_TYPE="SGX"
export TEE_ID="sgx-node"
export REGION_ID="us-east-1"
export CROSS_ATTESTATION_ENABLED="true"
export PARTNER_TEE_TYPE="SEV"

# Create node configuration
PUBLIC_IP=$(curl -s http://169.254.169.254/latest/meta-data/public-ipv4)
PRIVATE_IP=$(curl -s http://169.254.169.254/latest/meta-data/local-ipv4)
INSTANCE_ID=$(curl -s http://169.254.169.254/latest/meta-data/instance-id)

# Create mesh network configuration
mkdir -p /opt/rhombus/mesh
cat > /opt/rhombus/mesh/node_info.json << EOF
{
  "node_type": "SGX",
  "node_id": "${INSTANCE_ID}",
  "public_ip": "${PUBLIC_IP}",
  "private_ip": "${PRIVATE_IP}",
  "port": 7070,
  "region": "us-east-1"
}
EOF

# Set up parameter validation for WebAssembly
mkdir -p /opt/rhombus/validation
cat > /opt/rhombus/validation/parameter_config.json << EOF
{
  "validation": {
    "length_prefixed": true,
    "direct_format": true,
    "max_size": 1024,
    "format_detection": true
  },
  "cross_attestation": {
    "enabled": true,
    "partner_type": "SEV",
    "verification_ms_target": 100
  }
}
EOF

# Implement parameter format handler
cat > /opt/rhombus/validation/param_handler.js << EOF
/**
 * Parameter format detection and validation handler
 * Supports both length-prefixed and direct parameter formats
 */
function validateParameter(buffer, expectedSize) {
  if (buffer.length < 4) {
    console.log("Parameter too short, using direct format");
    return { format: "direct", data: buffer };
  }

  // Check if first 4 bytes could be a reasonable length prefix
  const lengthValue = buffer.readUInt32LE(0);

  if (lengthValue > 0 && lengthValue <= 1024 && lengthValue + 4 <= buffer.length) {
    console.log("Detected length-prefixed format, length:", lengthValue);
    return { 
      format: "length-prefixed", 
      data: buffer.slice(4, 4 + lengthValue) 
    };
  } else {
    console.log("Using direct format, no valid length prefix detected");
    return { format: "direct", data: buffer };
  }
}

module.exports = { validateParameter };
EOF

# Install monitoring service
cat > /opt/rhombus/tee/status.sh << 'EOF'
#!/bin/bash
IP=$(curl -s http://169.254.169.254/latest/meta-data/public-ipv4)
ID=$(curl -s http://169.254.169.254/latest/meta-data/instance-id)
echo "{\"node_type\":\"SGX\",\"id\":\"$ID\",\"ip\":\"$IP\",\"status\":\"running\",\"timestamp\":\"$(date -u +"%Y-%m-%dT%H:%M:%SZ\")\"}" > /var/www/html/status.json
EOF
chmod +x /opt/rhombus/tee/status.sh

# Set up simple web server to expose status
apt-get install -y apache2
echo '*/5 * * * * root /opt/rhombus/tee/status.sh' > /etc/cron.d/tee-status
systemctl enable apache2
systemctl restart apache2

# Write node info to publicly accessible location
mkdir -p /var/www/html
cp /opt/rhombus/mesh/node_info.json /var/www/html/
chown -R www-data:www-data /var/www/html/

echo "SGX node setup complete"

